class Solution {
public:
    const int MOD = 1337;

    int modPow(int a, int k) {
        int res = 1;
        a %= MOD;
        for (int i = 0; i < k; ++i)
            res = (res * a) % MOD;
        return res;
    }

    int superPow(int a, vector<int>& b) {
        if (b.empty()) return 1;
        int last = b.back(); b.pop_back();
        return modPow(superPow(a, b), 10) * modPow(a, last) % MOD;
    }
};
